import {createBoardAudio,moveSound} from './board-audio.js';
export const defaults={language:'it',theme:'dark',coordinates:true,legal:true,sound:false,volume:.5,quality:'deep',coachDetail:'compact',coachTone:'warm',coachHints:true,coachFrequency:'all',coachPreset:'milo',board:'amethyst',accent:'apricot',boardFrame:'classic',pieceStyle:'classic',avatarColor:'sage',avatarShape:'round',avatarEyes:'friendly',avatarAccessory:'none',coachName:'Milo'};
const choices={language:['it','en','es','fr','de'],theme:['system','light','dark'],quality:['quick','standard','deep'],coachDetail:['guided','compact'],coachTone:['warm','direct','quiet'],coachFrequency:['all','errors'],coachPreset:['milo','astra','nox','custom'],board:['amethyst','lavender','green','walnut','slate','ocean','sand','rose'],accent:['apricot','jade','violet'],boardFrame:['classic','wood','light'],pieceStyle:['classic','warm','contrast'],avatarColor:['sage','sky','plum','sun','coral','mint','ice','copper'],avatarShape:['round','square','cat','fox'],avatarEyes:['friendly','focused','happy','wink'],avatarAccessory:['none','glasses','crown','headphones','scarf','bow']};
export function sanitizeSettings(value){const out={...defaults};if(!value||typeof value!=='object')return out;for(const key of Object.keys(defaults)){if(choices[key]?.includes(value[key]))out[key]=value[key];else if(typeof defaults[key]==='boolean'&&typeof value[key]==='boolean')out[key]=value[key]}if(typeof value.coachName==='string')out.coachName=value.coachName.trim().slice(0,18)||defaults.coachName;if(typeof value.volume==='number'&&Number.isFinite(value.volume))out.volume=Math.max(0,Math.min(1,value.volume));out.quality="deep";return out}
let settings=defaults;try{settings=sanitizeSettings(JSON.parse(localStorage.getItem('plystreak-settings')))}catch{}
export const getSettings=()=>({...settings});
export function saveSettings(patch){settings=sanitizeSettings({...settings,...patch});let saved=true;try{localStorage.setItem('plystreak-settings',JSON.stringify(settings))}catch{saved=false}applySettings();window.dispatchEvent(new CustomEvent('ply-settings',{detail:settings}));return saved}
export function applySettings(){if(typeof document==='undefined')return;const root=document.documentElement;root.dataset.theme=settings.theme==='system'?(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'):settings.theme;root.dataset.coordinates=String(settings.coordinates);root.dataset.legal=String(settings.legal);root.dataset.board=settings.board;root.dataset.accent=settings.accent;root.dataset.boardFrame=settings.boardFrame;root.dataset.pieceStyle=settings.pieceStyle;document.querySelector('meta[name="theme-color"]')?.setAttribute('content',root.dataset.theme==='dark'?'#170e18':'#f7efe6')}
export const escapeHTML=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function avatarSVG(value=settings){
 const s=sanitizeSettings(value);
 const palettes={sage:['#c8d9c3','#536d5c'],sky:['#bddde8','#496a7c'],plum:['#ddc5db','#76566f'],sun:['#f3d49b','#816148'],coral:['#edb6a9','#814e51'],mint:['#b6d8ce','#426e67'],ice:['#d3edf3','#395778'],copper:['#ebb994','#77442d']};
 const [color,ink]=palettes[s.avatarColor];
 const shape=s.avatarShape==='fox'?'<path d="M34 36l27 13q19-7 38 0l27-13-7 53q-8 20-39 37-31-17-39-37Z"/>':s.avatarShape==='square'?'<rect x="34" y="34" width="92" height="91" rx="29"/>':s.avatarShape==='cat'?'<path d="M38 72 36 36l26 14q18-8 36 0l26-14-2 36v15q0 37-42 37T38 87Z"/>':'<circle cx="80" cy="79" r="47"/>';
 const eyes=s.avatarEyes==='wink'?'<path d="M56 80q8-8 16 0m22-4v7"/>':s.avatarEyes==='happy'?'<path d="M59 78q6-7 12 0m18 0q6-7 12 0"/>':s.avatarEyes==='focused'?'<path d="M59 76h12m18 0h12M65 79v3m30-3v3"/>':'<path d="M65 77v7m30-7v7"/>';
 const accessory=s.avatarAccessory==='scarf'?'<path d="M48 108q30 16 64-1l-4 12-13 3 8 16-14 3-9-18q-17 1-30-6Z" fill="#c36349" stroke="#693b31" stroke-width="2"/>':s.avatarAccessory==='bow'?'<path d="M80 120l-18-9v19l18-8 18 8v-19Z" fill="#746197" stroke="#473657" stroke-width="2"/><circle cx="80" cy="121" r="4" fill="#f0bd80"/>':s.avatarAccessory==='glasses'?`<g fill="none" stroke="${ink}" stroke-width="3"><rect x="49" y="69" width="28" height="23" rx="9"/><rect x="83" y="69" width="28" height="23" rx="9"/><path d="M77 78h6"/></g>`:s.avatarAccessory==='crown'?`<path d="m116 105 3 6 7 1-5 5 1 7-6-3-6 3 1-7-5-5 7-1Z" fill="#e9a173" stroke="${ink}" stroke-width="2"/>`:s.avatarAccessory==='headphones'?`<g aria-hidden="true"><path d="M52 42 47 17l20 10 13-18 13 18 20-10-5 25Z" fill="#e9a173" stroke="${ink}" stroke-width="3" stroke-linejoin="round"/><circle cx="80" cy="32" r="3" fill="${ink}"/></g>`:'';
 return `<svg viewBox="0 0 160 160" role="img" aria-label="Avatar illustrato del coach" xmlns="http://www.w3.org/2000/svg"><circle cx="80" cy="80" r="75" fill="${ink}" opacity=".15"/><circle cx="80" cy="80" r="67" fill="none" stroke="${color}" stroke-width="2" stroke-dasharray="3 5"/><g fill="${color}" stroke="${ink}" stroke-width="3.5" stroke-linejoin="round">${shape}</g><ellipse cx="53" cy="92" rx="7" ry="4" fill="#e9a173" opacity=".35"/><ellipse cx="107" cy="92" rx="7" ry="4" fill="#e9a173" opacity=".35"/><g fill="none" stroke="${ink}" stroke-width="4" stroke-linecap="round">${eyes}<path d="M70 101q10 8 20 0"/></g>${accessory}<path d="M66 132h28m-23 6h18" stroke="${ink}" stroke-width="3" stroke-linecap="round" opacity=".7"/></svg>`;
}
const boardAudio=createBoardAudio({getPreferences:()=>settings,createContext:()=>new(window.AudioContext||window.webkitAudioContext)(),createAudio:src=>new Audio(src)});
export function playSound(kind='move'){if(typeof document!=='undefined'&&document.hidden)return false;return boardAudio.play(kind)}
export function playMoveSound(chess,move,options){return playSound(moveSound(chess,move,options))}
if(typeof window!=='undefined'){window.addEventListener('pointerdown',()=>boardAudio.unlock(),{passive:true});window.addEventListener('pointerup',()=>boardAudio.unlock(),{passive:true});window.addEventListener('keydown',()=>boardAudio.unlock());window.addEventListener('ply-settings',()=>{boardAudio.stop();boardAudio.unlock()});document.addEventListener('visibilitychange',()=>{if(document.hidden)boardAudio.stop()});applySettings();matchMedia('(prefers-color-scheme: dark)').addEventListener('change',applySettings);window.addEventListener('storage',e=>{if(e.key==='plystreak-settings'){try{settings=sanitizeSettings(JSON.parse(e.newValue));applySettings();window.dispatchEvent(new CustomEvent('ply-settings',{detail:settings}))}catch{}}})}
